econdaryexternalid,\r\n        ac2.altpermissionlevel AS secondaryaltpermissionlevel,\r\n        luc.coursenote, c.personid, c.registrationstatus,c.CoursesID,c.dateAdded,c.dateinstructorlastviewed,c.datestudentlastviewed,\r\n\t\tc.DateLetterIssued,c.DateLetterReturned,\r\n\t\tp.PersonID, p.firstname, p.lastname, p.middlename, p.student_no, pg.mingroupid,\r\n\t\tpwhoadded.PersonID as whoaddedpersonid, pwhoadded.firstname as whoaddedfirstname, pwhoadded.lastname as whoaddedlastname, pwhoadded.middlename as whoaddedmiddlename, pwhoadded.student_no as whoaddedstudent_no, pgwhoadded.mingroupid as whoaddedmingroupid\r\nFROM    courses c LEFT JOIN lucourses luc ON luc.lucourseid=c.lucourseid\r\n        LEFT JOIN lucoursedata lucd ON lucd.lucoursedataid=luc.subjectid\r\n        LEFT JOIN lucoursedata lucd2 ON lucd2.lucoursedataid=luc.instructorid\r\n        LEFT JOIN lucourseinstructor lci ON lci.lucourseid=luc.lucourseid\r\n        LEFT JOIN lucoursedata lucd3 ON lucd3.lucoursedataid=lci.instructorid\r\n        LEFT JOIN timetable tt ON tt.timetabletype='C' AND tt.lucourseid=luc.lucourseid\r\n        LEFT JOIN lucoursealternatecontact ac ON ac.alternatecontactid=luc.alternatecontactid\r\n        LEFT JOIN LuCourseAltContact lucac ON lucac.lucourseid=luc.lucourseid\r\n        LEFT JOIN lucoursealternatecontact ac2 ON ac2.alternatecontactid=lucac.alternatecontactid\r\n\t\tLEFT JOIN People p ON p.PersonId = @pid\r\n\t\tLEFT JOIN peoplemingroup pg ON pg.PersonID = @pid\r\n\t\tLEFT JOIN People pwhoadded ON pwhoadded.PersonId = c.whoAdded\r\n\t\tLEFT JOIN peoplemingroup pgwhoadded ON pgwhoadded.PersonID = c.whoAdded\r\nWHERE   c.personid=@pid\r\n        AND (c.registrationstatus IS NULL OR NOT c.registrationstatus=2)\r\n        AND (NOT ( enddate <= @sd OR startdate > @ed))\r\n        AND NOT luc.lucourseid IS NULL\r\nORDER BY luc.startdate,luc.duration,luc.term,lucd.altlookupstring,luc.course,luc.[section],luc.timeofday,luc.lucourseid";

