		// Token: 0x040001FC RID: 508
		internal const string QS_UNIQUE_COURSE_DATE_RANGES_BY_DATE_RANGE = "DECLARE @sd datetime = DATEADD(D, 0, DATEDIFF(D, 0, @startdate))\r\nDECLARE @ed datetime = DATEADD(D, 0, DATEDIFF(D, 0, @enddate))\r\n\r\nSELECT\tDISTINCT DATEADD(D, 0, DATEDIFF(D, 0, luc.startdate)) AS startdate,DATEADD(D, 0, DATEDIFF(D, 0, luc.enddate)) AS enddate,COUNT(lucourseid) AS CourseCount \r\nFROM\tlucourses luc \r\nWHERE\tNOT ( ( luc.enddate<@sd ) OR (luc.startdate > @ed ) )\r\nGROUP BY DATEADD(D, 0, DATEDIFF(D, 0, luc.startdate)),DATEADD(D, 0, DATEDIFF(D, 0, luc.enddate))\r\nORDER BY DATEADD(D, 0, DATEDIFF(D, 0, luc.startdate)),DATEADD(D, 0, DATEDIFF(D, 0, luc.enddate))";

