		// Token: 0x04000217 RID: 535
		internal const string QI_INSTRUCTOR = "IF LEN(COALESCE(@instructorexternalid,',')) < 1 AND LEN(COALESCE(@instructorusername,',')) < 1 AND LEN(COALESCE(@instructoremployeeid,',')) < 1 AND LEN(COALESCE(@instructoremail,',')) < 1\r\n\tSELECT 0 AS lucoursedataid\r\nELSE IF EXISTS(\r\nSELECT lucoursedataid FROM lucoursedata lucd \r\nWHERE lucd.lookuplisttype=1 AND \r\n    (\r\n        (LEN(COALESCE(@instructorexternalid,',')) > 0 AND lucd.ExternalId=@instructorexternalid)\r\n\t\t    OR\r\n\t\t(LEN(COALESCE(@instructorusername,',')) > 0 AND lucd.username=@instructorusername)\r\n\t\t    OR\r\n\t\t(LEN(COALESCE(@instructoremployeeid,',')) > 0 AND lucd.id=@instructoremployeeid)\r\n            OR\r\n        (LEN(COALESCE(@instructoremail,',')) > 0 AND lucd.username=@instructoremail)\r\n    )\r\n)\r\n    SELECT TOP 1 lucoursedataid FROM lucoursedata lucd \r\n    WHERE lucd.lookuplisttype=1 AND \r\n    (\r\n        (LEN(COALESCE(@instructorexternalid,',')) > 0 AND lucd.ExternalId=@instructorexternalid)\r\n\t    \tOR\r\n\t\t(LEN(COALESCE(@instructorusername,',')) > 0 AND lucd.username=@instructorusername)\r\n\t\t    OR\r\n\t\t(LEN(COALESCE(@instructoremployeeid,',')) > 0 AND lucd.id=@instructoremployeeid)\r\n            OR\r\n        (LEN(COALESCE(@instructoremail,',')) > 0 AND lucd.username=@instructoremail)\r\n    )\r\n\tORDER BY lucd.luCourseDataID DESC\r\nELSE\r\nBEGIN\r\n    INSERT INTO lucoursedata (lookuplisttype,lookupstring,altlookupstring,email,phone,username,id,externalid,exemptfromdatasync) \r\n    VALUES (1,@instructorname,@instructorname,@instructoremail,@instructorphone,@instructorusername,@instructoremployeeid,@instructorexternalid,@exemptfromdatasync);\r\n\r\n    SELECT CAST(SCOPE_IDENTITY() AS INT) AS lucoursedataid\r\nEND";

